-- 050. Валентина: без сокращений в речи (25.11, на слух): «Вы из ГУВД» → «Вы из милиции», «в АОН» → «в определителе».
begin;
update characters set intro_text = replace(intro_text, '— Вы из ГУВД.', '— Вы из милиции.') where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R09' then jsonb_set(r, '{text}', to_jsonb('"Вы кладёте перед ней заключение Кана и пейджер из арыка. Говорите: если вам угрожают, молчание никого не защитит. Защитить может только милиция.\nНа кухне перестают звенеть посудой.\n— Я тридцать лет учила детей говорить правду. Тридцать лет. А сама… — Долгая пауза. — Хорошо. Хорошо. Четверг, около девяти. Автомат. Шестьдесят тысяч. И если в милицию — Дашу мы больше не увидим. — Сбивается. — Мы с Данияром собрали сорок. Виктору я сказала: Игорь в Бишкеке. Суббота… половина четвёртого. Второй звонок, номер в определителе остался. Данияр отвёз деньги. Вернулся. С половины восьмого до половины второго был со мной. Ждали. — Голос ломается. — Я молчала ради Даши. Ради Даши."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
commit;
select left(intro_text, 200) from characters where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
